// Maps Supabase / PostgREST / PostgreSQL errors to safe HTTP responses.
//
// Clients get a status, a stable code and a short message. They never get SQL,
// constraint or table names, row data (`details`), hints or stack traces.
// Messages written by HireSwipe's own database functions (RAISE EXCEPTION in
// supabase/migrations) are meant for API users and are passed through;
// messages generated by PostgreSQL itself are replaced with generic text.

// PostgreSQL-generated messages that name tables, constraints or columns.
const POSTGRES_GENERATED = /violates|row-level security|permission denied|relation "|column "|constraint "/i

const GENERIC = {
  FORBIDDEN: 'You do not have permission to perform this action.',
  CONFLICT: 'A record with these details already exists.',
  INVALID_REFERENCE: 'A referenced record does not exist.',
  RULE_VIOLATION: 'The request violates a data rule.',
  VALIDATION_ERROR: 'The request contains an invalid value.',
  NOT_FOUND: 'Resource not found.',
  INVALID_TOKEN: 'Invalid or expired Supabase Auth token.',
  SERVICE_UNAVAILABLE: 'The database is temporarily unavailable.',
  INTERNAL_ERROR: 'Internal server error',
}

/** Our own RAISE messages are safe to show; PostgreSQL's are not. */
function ownMessageOr(message, fallback) {
  return message && !POSTGRES_GENERATED.test(message) ? message : fallback
}

function result(status, code, message) {
  return { status, code, message: message ?? GENERIC[code] }
}

/**
 * @param {{ code?: string, message?: string }} error  error from supabase-js
 * @returns {{ status: number, code: string, message: string }}
 */
export function mapDbError(error) {
  const pgCode = error?.code ?? ''
  const message = error?.message ?? ''

  switch (pgCode) {
    // PostgREST: .single()/.maybeSingle() matched no row (or several)
    case 'PGRST116':
      return result(404, 'NOT_FOUND')
    // PostgREST: a field in the request body/columns is not a column of the
    // table. PostgREST itself answers 400. Routes validate against an allowlist
    // first, so seeing this usually means the allowlist and the schema differ;
    // the log keeps PostgREST's message (it names the column), the client does not.
    case 'PGRST204':
      return result(400, 'VALIDATION_ERROR', 'The request contains an unknown field.')
    // PostgREST: JWT rejected (expired, malformed, claims invalid)
    case 'PGRST301':
    case 'PGRST302':
    case 'PGRST303':
      return result(401, 'INVALID_TOKEN')

    // insufficient_privilege: RLS denial, missing grant, or 004's RAISE ... ERRCODE '42501'
    case '42501':
      return result(403, 'FORBIDDEN', ownMessageOr(message, GENERIC.FORBIDDEN))
    // unique_violation
    case '23505':
      return result(409, 'CONFLICT')
    // foreign_key_violation (also 004's 'Job not found')
    case '23503':
      return result(422, 'INVALID_REFERENCE', ownMessageOr(message, GENERIC.INVALID_REFERENCE))
    // check_violation: CHECK constraints and 004's business rules
    case '23514':
      return result(422, 'RULE_VIOLATION', ownMessageOr(message, GENERIC.RULE_VIOLATION))
    // invalid_parameter_value: 004's create_company_with_owner input checks
    case '22023':
      return result(422, 'RULE_VIOLATION', ownMessageOr(message, GENERIC.RULE_VIOLATION))
    // RAISE EXCEPTION without ERRCODE (003/004 triggers)
    case 'P0001':
      return message.startsWith('Unauthorized')
        ? result(403, 'FORBIDDEN', ownMessageOr(message, GENERIC.FORBIDDEN))
        : result(422, 'RULE_VIOLATION', ownMessageOr(message, GENERIC.RULE_VIOLATION))

    // Malformed input that reached the database
    case '23502': // not_null_violation
      return result(400, 'VALIDATION_ERROR', 'A required value is missing.')
    case '22P02': // invalid_text_representation (bad uuid, enum, number)
      return result(400, 'VALIDATION_ERROR', 'A value has an invalid format.')
    case '22001': // string_data_right_truncation
      return result(400, 'VALIDATION_ERROR', 'A value is too long.')
    case '22003': // numeric_value_out_of_range
      return result(400, 'VALIDATION_ERROR', 'A numeric value is out of range.')
    case '22007': // invalid_datetime_format
    case '22008': // datetime_field_overflow
      return result(400, 'VALIDATION_ERROR', 'A date or time value is invalid.')
  }

  // supabase-js reports network failures without a code
  if (!pgCode && /fetch failed|ECONNREFUSED|ENOTFOUND|ETIMEDOUT|network/i.test(message)) {
    return result(503, 'SERVICE_UNAVAILABLE')
  }

  // 42P17 (policy recursion), 42883 / PGRST202 (missing function, e.g. migration
  // not applied) and anything unexpected: generic 500, details stay in the log.
  return result(500, 'INTERNAL_ERROR')
}

/**
 * Log a database error server-side (code and message only: `details` can
 * contain row data) and send the mapped response.
 */
export function sendDbError(res, error, context) {
  const mapped = mapDbError(error)
  const log = mapped.status >= 500 ? console.error : console.warn
  log(`[db] ${context}: ${mapped.status} ${error?.code || 'NO_CODE'} ${error?.message ?? ''}`)
  return res.status(mapped.status).json({ error: { code: mapped.code, message: mapped.message } })
}
